CREATE DEFINER=`root`@`localhost` PROCEDURE `prc_CreateNotice`(P_ID VARCHAR(20),
	P_Notice VARCHAR(200),
	OUT P_RowCnt INT)
    COMMENT '???ӹ??'
BEGIN
	SET P_RowCnt = 0;

	INSERT INTO Notice(ID,Notice) 
	SELECT ID,Notice 
	FROM Admin
	WHERE AGENCY = ID 
		AND ID NOT IN(SELECT ID FROM Notice) 
		AND ID != P_ID;
	SET P_RowCnt = P_RowCnt + FOUND_ROWS();
	
	UPDATE Notice 
	SET Notice = Notice 
	WHERE ID IN (SELECT ID FROM Admin WHERE AGENCY = P_ID);
	SET P_RowCnt = P_RowCnt + FOUND_ROWS();
	
END ;;
DELIMITER ;
